import { type SQL, sql } from "drizzle-orm";
import { type AnyPgColumn, bigint, customType, timestamp, uuid } from "drizzle-orm/pg-core";
import { v7 as uuidv7 } from "uuid";

// UUID v7 primary key, generated by the application (PostgreSQL 16 has no uuidv7()).
export function id() {
  return uuid("id")
    .primaryKey()
    .$defaultFn(() => uuidv7());
}

export function createdAt() {
  return timestamp("created_at", { withTimezone: true }).notNull().defaultNow();
}

// `<column> in ('a', 'b')` for a CHECK built from an exported constant. The values go into the SQL
// text, so each must be a plain lower-case word.
export function inList(column: AnyPgColumn, values: readonly string[]): SQL {
  if (values.length === 0) throw new Error("inList: no values");
  for (const v of values) {
    if (!/^[a-z0-9_]+$/.test(v)) throw new Error(`inList: not a plain value: ${v}`);
  }
  return sql`${column} in (${sql.raw(values.map((v) => `'${v}'`).join(", "))})`;
}

// Money is an integer in minor units (R4); in TypeScript it is a bigint.
export function money(name: string) {
  return bigint(name, { mode: "bigint" });
}

// drizzle-orm 0.45 has no built-in bytea, and importing one crashes drizzle-kit.
export const bytea = customType<{ data: Buffer; driverData: Buffer }>({
  dataType: () => "bytea",
});
